const { useState } = React;
const products = ['셔츠', '모자', '신발'];

function Search() {
  const [query, setQuery] = useState('');
  const filtered = products.filter((name) => name.includes(query));

  return (
    <main>
      <input value={query} onChange={(event) => setQuery(event.currentTarget.value)} />
      <ul>{filtered.map((name) => <li key={name}>{name}</li>)}</ul>
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Search />);
